solution:
use xiom.io;

use xiom.string;
interface Greetable {
  fn greet() -> Str;
}

interface Displayable {
  fn display() -> Str;
}

type Person = {
  name: Str;
  age: Int;
}

fn Person.greet(self) -> Str {
  return "Hi, I'm " + self.name;
}

fn Person.display(self) -> Str {
  return self.name + " (" + to_string(self.age) + ")";
}

fn print_profile[T: Greetable + Displayable](thing: &T) {
  io.println(thing.greet());
  io.println(thing.display());
}

fn main() -> Int {
  let p = Person{ name: "Alex", age: 25 };
  print_profile(&p);
  return 0;
}
